/// `adapter` must be null or point to a live `Model701CallbackAdapter`, valid for the
/// duration of the call.
unsafe fn model_701_c_visit_read(
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model701;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *const Model701CallbackAdapter).as_ref() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_701_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_701_c_visit_write(
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let _ = (adapter, buffer);
    let model = Model701;
    cursor.visit_source_block(model.model_length(), |_, _, _| {
        Err(ModbusException::IllegalDataAddress)
    });
}

/// Build a [`SunspecAdapter`] for model 701 backed by a callback adapter.
#[unsafe(no_mangle)]
pub extern "C" fn sunspec_model_701_callback(
    adapter: *mut Model701CallbackAdapter,
) -> SunspecAdapter {
    SunspecAdapter {
        model_spec: &SUNSPEC_MODEL_701,
        adapter: adapter as *mut c_void,
    }
}
